changeSet.sql:
SET LOCAL lock_timeout = '5s';

-- ---- the manifest
CREATE OR REPLACE FUNCTION nexus.catalog_document_chunks_name_from_chunk()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_chunk_id  bigint;
    v_stored    text;
BEGIN
    IF NEW.collection_id IS NULL THEN
        RETURN NEW;
    END IF;
    -- An UPDATE that does not move the key (a stamp of collection_id, a position change) needs no lookup.
    IF TG_OP = 'UPDATE'
       AND NEW.collection IS NOT DISTINCT FROM OLD.collection
       AND NEW.tenant_id = OLD.tenant_id
       AND NEW.chash = OLD.chash
       AND NEW.embedding_model IS NOT DISTINCT FROM OLD.embedding_model THEN
        RETURN NEW;
    END IF;
    -- 1. The chunk under the name the writer supplied (the primary key).
    SELECT c.collection_id INTO v_chunk_id
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection = NEW.collection
       AND c.chash = NEW.chash AND c.embedding_model = NEW.embedding_model;
    IF FOUND AND (v_chunk_id IS NULL OR v_chunk_id = NEW.collection_id) THEN
        RETURN NEW;
    END IF;
    -- 2. The chunk of the child's collection, whatever name it is stored under.
    -- A child row whose collection id belongs to a RETIRED registry row (a tombstone) is not a writer's: it is the ON UPDATE CASCADE of a
    -- pre-gate-3 name-path rename, which retires the old row, gives the collection a new id and renames the chunks first; the cascade
    -- renames each child by name and the id repair follows. Step 1 missed (the chunk now carries the new id), and step 2 would scan the
    -- tenant's leaf once per cascaded row, N x N. One probe on the registry's (tenant_id, collection_id) key skips it.
    IF EXISTS (SELECT 1 FROM nexus.catalog_collections r
                WHERE r.tenant_id = NEW.tenant_id AND r.collection_id = NEW.collection_id AND r.superseded_by <> '') THEN
        RETURN NEW;
    END IF;
    SELECT c.collection INTO v_stored
      FROM nexus.chunks c
     WHERE c.tenant_id = NEW.tenant_id AND c.collection_id = NEW.collection_id
       AND c.chash = NEW.chash AND c.embedding_model = NEW.embedding_model
     LIMIT 1;
    IF NOT FOUND OR v_stored = NEW.collection THEN
        RETURN NEW;
    END IF;
    IF pg_catalog.current_setting('nexus.child_name_fix_logged', true) IS DISTINCT FROM 'on' THEN
        PERFORM pg_catalog.set_config('nexus.child_name_fix_logged', 'on', true);
        RAISE LOG 'RDR-229: nexus.% took the chunk''s stored collection name (supplied %, stored %, chunk %, application %, pid %); further replacements in this transaction are not logged',
            TG_TABLE_NAME, NEW.collection, v_stored, pg_catalog.substr(pg_catalog.encode(NEW.chash, 'hex'), 1, 12),
            pg_catalog.current_setting('application_name'), pg_catalog.pg_backend_pid();
    END IF;
    NEW.collection := v_stored;
    RETURN NEW;
END;
$function$;

-- ---- chunk_orphaned_at
CREATE OR REPLACE FUNCTION nexus.chunk_orphaned_at_name_from_chunk()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_chunk_id  bigint;
    v_stored    text;
BEGIN
    IF NEW.collection_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND NEW.collection IS NOT DISTINCT FROM OLD.collection
       AND NEW.tenant_id = OLD.tenant_id
       AND NEW.chash = OLD.chash
       AND NEW.embedding_model IS NOT DISTINCT FROM OLD.embedding_model THEN
        RETURN NEW;
