        RETURN NEW;
    END IF;
    IF pg_catalog.current_setting('nexus.child_name_fix_logged', true) IS DISTINCT FROM 'on' THEN
        PERFORM pg_catalog.set_config('nexus.child_name_fix_logged', 'on', true);
        RAISE LOG 'RDR-229: nexus.% took the chunk''s stored collection name (supplied %, stored %, chunk %, application %, pid %); further replacements in this transaction are not logged',
            TG_TABLE_NAME, NEW.collection, v_stored, pg_catalog.substr(pg_catalog.encode(NEW.chash, 'hex'), 1, 12),
            pg_catalog.current_setting('application_name'), pg_catalog.pg_backend_pid();
    END IF;
    NEW.collection := v_stored;
    RETURN NEW;
